contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to) public {
        // Deposit some Ether so the contract is non-empty and migrateTo has an effect.
        c.deposit{value: 1}();

        // Read the before-balance of the contract through its public surface.
        uint256 beforeBalance = address(c).balance;

        // Call migrateTo as the test contract, which is NOT the creator (creator is the deployer of c).
        bool reverted;
        try c.migrateTo(to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: migrateTo by a non-creator must revert, and since it reverted,
        // the contract's Ether balance must be unchanged.
        assert(reverted && address(c).balance == beforeBalance);
    }

    receive() external payable {}
}

